-- 1. Supplementary Zone Definitions
INSERT INTO game.zones (id, name, dat_path, is_seamless)
VALUES
    (100, 'West Ronfaure', 'ROM/1/30.DAT', false),
    (102, 'La Theine Plateau', 'ROM/1/2.DAT', false),
    (233, 'Chateau d''Oraguille', 'ROM/1/38.DAT', false),
    (244, 'Upper Jeuno', 'ROM/1/40.DAT', false),
    (245, 'Lower Jeuno', 'ROM/1/41.DAT', false),
    (248, 'Selbina', 'ROM/1/44.DAT', false),
    (249, 'Mhaura', 'ROM/1/45.DAT', false)
ON CONFLICT (id) DO NOTHING;

-- 2. NPC Master Table (1:1 with authentic LandSandBoat schema & spawn state)
CREATE TABLE game.npc_list (
    id            BIGINT PRIMARY KEY,
    name          VARCHAR(64) NOT NULL,
    pos_x         REAL NOT NULL DEFAULT 0.0,
    pos_y         REAL NOT NULL DEFAULT 0.0,
    pos_z         REAL NOT NULL DEFAULT 0.0,
    pos_rot       SMALLINT NOT NULL DEFAULT 0,
    zone_id       INT NOT NULL REFERENCES game.zones (id) ON DELETE CASCADE,
    status        VARCHAR(32) NOT NULL DEFAULT 'normal',
    entity_flags  INT NOT NULL DEFAULT 0,
    animation_sub SMALLINT NOT NULL DEFAULT 0,
    name_prefix   SMALLINT NOT NULL DEFAULT 0,
    moving        SMALLINT NOT NULL DEFAULT 0,
    look_type     VARCHAR(32),
    race_id       SMALLINT NOT NULL DEFAULT 0,
    face_id       SMALLINT NOT NULL DEFAULT 0,
    head          INT NOT NULL DEFAULT 0,
    body          INT NOT NULL DEFAULT 0,
    hands         INT NOT NULL DEFAULT 0,
    legs          INT NOT NULL DEFAULT 0,
    feet          INT NOT NULL DEFAULT 0,
    main_weapon   INT NOT NULL DEFAULT 0,
    sub_shield    INT NOT NULL DEFAULT 0,
    ranged        INT NOT NULL DEFAULT 0,
    model_id      INT NOT NULL DEFAULT 0,
    widescan      BOOLEAN NOT NULL DEFAULT false
);

CREATE INDEX idx_npc_list_zone_id ON game.npc_list(zone_id);

